function highestProfession(values){return TIERS.slice().reverse().map(t=>String(values[`profession_${t}_name`]||'').trim()).find(Boolean)||'survivor';}
function talentGuide(){
 const groups=[['Ancestral Talents',[
 ['Underfoot / Deadly Aim / Warg-blooded','+1 Agility Bonus for each keyword.'],['Mountain Among Men / Inhuman Strength / Big Folk / Monstrous Body','+1 Brawn Bonus for each keyword.'],['Combat Prowess','+1 Combat Bonus.'],['Saber-toothed / Mighty Thews / Horrific Claws / Razor-sharp Claws','+5% Melee for each keyword.'],['Blue-blooded / Fieldwarden','+5% Ranged for each keyword.'],['Jack of All Trades','+5% to skills with no purchased ranks.'],['Servant of the Steward','+2 Peril Threshold unless Stressed, Frightened or Terrified.'],['Broad-bellied','+2 Peril Threshold unless starving.'],['Ironclad','+2 Peril Threshold while wearing armor.'],['Hide of Scales / Leathery Skin','+2 Damage Threshold each while unarmored.'],['Warg-blooded','+3 Damage Threshold when Seriously/Grievously Wounded or Dying.'],['Upper Crust / Bend Like a Reed','Use Fellowship Bonus for Damage Threshold if higher than Brawn Bonus.'],['Strength of the Mountain','Weapon and tool limits become 6 each.'],['Prehensile Tail','Forgives one excess weapon or tool.'],['Liquid Poise','Use higher of Agility/Perception Bonus for Initiative, and add +1.'],['Steam-powered','+1/+2/+3 Initiative at the −5/−10/−15 Peril stages.']]],['Professional Talents',[
 ['Spiritual Defense','+1 Damage Threshold per scar; blocked by Heavy armor.'],['The End Is Nigh','+3 Damage Threshold.'],['Call to Arms','Supply maximum uses Combat Bonus instead of Intelligence Bonus.'],['Fair Share','+2 weapon slots and +2 tool slots.']]],['General Talents',[
 ['Salt of the Earth','+3 Peril Threshold and +1 Damage Threshold.'],['Instincts','+1 Initiative.'],['Supernatural Paranoia','+3 Initiative while Stressed, Frightened or Terrified.']]]];
 return `<section class="card talent-rule-guide"><h3>Automatically Calculated Talents</h3><p class="info-label">Enter these keywords in talent names and mark Purchased to activate their effects. Descriptions are for your notes.</p><div class="talent-rule-columns">${groups.map(([heading,entries])=>`<div><h4>${heading}</h4><dl>${entries.map(([name,effect])=>`<div><dt>${esc(name)}</dt><dd>${esc(effect)}</dd></div>`).join('')}</dl></div>`).join('')}</div></section>`;
}
function advancementLayout(){return SECTIONS.filter(s=>group(s)==='Advancement').map(s=>section(s)+(s.title==='Reward Points'?talentGuide():'')).join('');}
function magicRecords(kind,values=current.values){const config=magicConfig(kind),fields=SECTIONS.find(s=>s.title===config.title).fields;return Array.from({length:magicCount(values,kind)},(_,i)=>({index:i+1,fields:fields.slice(i*config.size,(i+1)*config.size)})).filter(record=>record.fields.some(f=>{const value=values[f.key];return value!==undefined&&value!==null&&String(value).trim()!==''&&String(value).trim()!=='None';}));}
function magicReadOnly(){return ['spell','ritual'].map(kind=>{const config=magicConfig(kind),records=magicRecords(kind);if(!records.length)return '';
 return `<section class="sheet-panel magic-readonly-section"><h3>${config.title} <span class="magic-entry-count">${records.length}</span></h3><div class="magic-readonly-grid">${records.map(record=>{const name=current.values[record.fields[0].key]||config.single+' '+record.index;return `<article class="magic-readonly-record"><h4>${esc(name)}</h4><dl>${record.fields.slice(1).map(f=>{const raw=current.values[f.key],option=f.options?.find(o=>o.value===raw),value=option?.label??raw;return raw!==undefined&&raw!==null&&String(raw).trim()!==''&&raw!=='None'?`<div class="${f.type==='textarea'?'magic-readonly-long':''}"><dt>${esc(f.label)}</dt><dd>${esc(value)}</dd></div>`:'';}).join('')}</dl></article>`;}).join('')}</div></section>`;}).join('');}
let overviewParts={};
function professionPrintSummary(){const v=current.values,ledger=calculate(v),currentTier=TIERS.slice().reverse().find(t=>String(v[`profession_${t}_name`]||'').trim())||'basic';
 return `<section class="sheet-panel"><h3>Profession Advancement</h3><div class="print-professions">${TIERS.map(t=>{const p=`profession_${t}_`,rows=[];
 const add=(label,key,toggle)=>{const val=v[p+key],purchased=[true,1,'1'].includes(v[p+'toggle_'+toggle]),selected=val&&val!=='None'&&String(val).trim();if(selected||purchased||t===currentTier)rows.push(`<li>${purchased?'■':'□'} <b>${esc(label)}:</b> ${esc(selected?val:'Not selected')}</li>`);};
 for(let i=1;i<=6;i++)add('Skill '+i,'skill_'+i,i);add('Attribute','attribute',7);add('Professional talent','profession_talent',8);add('Ancestral talent','ancestral_talent',9);for(let i=1;i<=6;i++)add('Bonus '+i,'bonus_'+i,9+i);for(let i=1;i<=3;i++)add('Talent '+i,'talent_'+i,15+i);
 return `<div><h4>${t[0].toUpperCase()+t.slice(1)} · ${esc(v[p+'name']||'—')} <span class="print-tier-cost">${(TIERS.indexOf(t)+1)*10} RP</span></h4><ul>${rows.join('')||'<li>—</li>'}</ul></div>`;}).join('')}</div><div class="print-rp-summary"><strong>Reward Points</strong><span>Total: ${Number(v.reward_points)||0}</span><span>Spent: ${ledger.spent}</span><span>Remaining: ${ledger.left}</span></div></section>`;
}
function printOrnaments(pageNumber=1){return `<svg class="print-ornaments" viewBox="0 0 718 1043" preserveAspectRatio="none" aria-hidden="true"><defs><g id="forge-corner-${pageNumber}" transform="scale(.65)" fill="none" stroke="currentColor" stroke-width="1"><path d="M14 100V14h86M20 78V20h58M14 55C31 55 35 37 35 24C35 42 51 44 62 35C49 48 48 57 56 67C43 59 30 65 27 79"/><path d="M24 37C13 27 19 16 29 21C35 24 33 31 28 29M38 24C28 13 16 19 21 29M30 60C17 61 19 50 25 51M60 30C61 17 50 19 51 25M20 88l-5 6-5-6 5-6z"/><path d="M72 14l6-4 6 4-6 4zM14 72l-4 6 4 6 4-6z" fill="currentColor" stroke="none"/></g><g id="forge-seal-${pageNumber}" fill="none" stroke="currentColor" stroke-width="1.2"><circle r="15"/><circle r="12" stroke-width=".5"/><path d="M-7 7L7-7l2-5-5 2L-9 5m2-1 5 5M7 7L-7-7l-2-5 5 2L9 5m-2-1-5 5"/><path d="M0-20l2 4-2 3-2-3zM0 20l2-4-2-3-2 3z"/></g></defs><path d="M104 14H614M104 1029H614M14 104V939M704 104V939" fill="none" stroke="currentColor" stroke-width=".55" opacity=".7"/><use href="#forge-corner-${pageNumber}"/><use href="#forge-corner-${pageNumber}" transform="translate(718 0) scale(-1 1)"/><use href="#forge-corner-${pageNumber}" transform="translate(0 1043) scale(1 -1)"/><use href="#forge-corner-${pageNumber}" transform="translate(718 1043) scale(-1 -1)"/><use href="#forge-seal-${pageNumber}" transform="translate(359 1029) scale(.55)"/><path d="M235 1029h98m52 0h98M235 1029l-5-3-5 3 5 3zM483 1029l5-3 5 3-5 3z" stroke="currentColor" stroke-width=".7" fill="none"/></svg>`;}

function printMarkup(){const p=overviewParts,hasMagic=['spell','ritual'].some(k=>magicRecords(k).length>0),total=hasMagic?3:2;
 const page=(number,title,body)=>`<section class="print-page">${printOrnaments(number)}<div class="print-top-spacer" aria-hidden="true"></div><div class="print-viewport"><div class="print-body">${body}${number===2?'':`<div class="print-spare-notes"><span>${number===1?'Chronicle & Session Notes':'Arcane Notes'}</span></div>`}</div></div><div class="print-running-foot"><span>ZWEIHÄNDER REFORGED</span><span>${number} / ${total}</span></div></section>`;
 return page(1,'Character & Combat',`<div class="print-bio-row"><div>${p.bio}</div><div class="print-character-side">${p.portrait}${p.goals}${p.reputation}</div></div><div class="print-combat-row">${p.skills}${p.peril}${p.damage}${p.initiative}</div>`)+page(2,'Equipment & Talents',`<div class="print-equipment">${p.weapons}${p.tools}${p.objects}${p.supplies}${p.titles}${p.burden}${p.silver}</div>${p.talents}${professionPrintSummary()}`)+(hasMagic?page(3,'Spells & Rituals',p.magic):'');
}
function printScale(width,height,availableWidth,availableHeight){return Math.min(1,availableWidth/Math.max(1,width),availableHeight/Math.max(1,height));}
function fitPrintPages(){document.querySelectorAll('#print-root .print-page').forEach(page=>{const viewport=page.querySelector('.print-viewport'),body=page.querySelector('.print-body'),notes=page.querySelector('.print-spare-notes'),width=viewport.clientWidth,height=viewport.clientHeight;body.style.transform='none';body.style.marginLeft='0';if(notes)notes.style.display='none';
 const fits=scale=>{body.style.width=`${width/scale}px`;return body.scrollHeight*scale<=height-2&&body.scrollWidth*scale<=width+1;};
 let scale=1;if(!fits(1)){let low=.02,high=1;for(let i=0;i<15;i++){const mid=(low+high)/2;if(fits(mid))low=mid;else high=mid;}scale=low;fits(scale);}
 const spare=(height-body.scrollHeight*scale)/scale;if(notes&&spare>85){notes.style.display='block';notes.style.height=`${spare-18}px`;}
 body.style.transform=`scale(${scale})`;});}
function fieldHint(key){
 if(/^attribute_/.test(key))return 'All purchased +5% attribute adjustments are applied first. The adjusted percentage’s tens digit is then added to purchased bonus advances, ancestral bonuses and custom bonuses.';
 if(/_bonus_custom$/.test(key))return 'Adds directly to this attribute bonus, affecting any threshold, initiative or capacity that uses it.';
 if(/^profession_.*_skill_/.test(key))return 'Matching Purchased checkbox grants one rank: +10%, capped at three ranks per skill.';
 if(/^profession_.*_bonus_/.test(key))return 'Matching Purchased checkbox adds +1 to the selected attribute bonus.';
 if(/^profession_.*_attribute$/.test(key))return 'Purchased adjustment adds +5% to the selected attribute and its skills.';
 if(key==='armor_qualities')return 'Keywords: Ruined sets armor DTh to 0; Maker\'s Mark adds 1 DTh; Ill-fitted gives −3 Initiative; Heavy blocks Spiritual Defense. Enter keywords in this field.';
 if(key==='armor_dth')return 'Added to Damage Threshold after armor qualities and Brawn Bonus requirement adjustments.';
 if(key==='armor_bb')return 'If unmet, reduces armor DTh by the shortfall (minimum 1). Ruined and Maker\'s Mark take precedence, as in the supplied sheet.';
 if(key==='armor_name')return 'A filled armor name or positive armor DTh counts as wearing armor for ancestral talents.';
 if(/^weapon_qualities_/.test(key))return 'Equipped only: Hardened adds +1 Peril Threshold; Defensive adds +1 Damage Threshold. Each bonus applies once. Ruined disables these benefits.';
 if(/^weapon_active_/.test(key))return 'Equip to enable Hardened / Defensive benefits. All named weapons count toward carrying limits.';
 if(/^weapon_name_/.test(key))return 'Every named weapon counts toward the carrying limit, equipped or otherwise.';
 if(/^tool_\d+$/.test(key))return 'Every filled tool slot counts toward carrying limits; excess items reduce Initiative.';
 if(/^object_\d+$/.test(key))return '“Talisman of [Skill]” adds +5% once. The supplied formulas omit this bonus for Thievery and Toughness.';
 if(key==='scars_number')return 'With purchased Spiritual Defense, each scar adds +1 Damage Threshold; Heavy armor blocks this bonus.';
 if(/^supply_rating_/.test(key))return 'Maximum Supply Rating uses Intelligence Bonus, or Combat Bonus with purchased Call to Arms. The limit appears on Overview.';
 if(key==='silver')return 'Each full 1,000 SP adds 1 burden and subtracts 1 Initiative, matching the supplied formula.';
 if(key==='burden_penalty')return 'Extra burden is subtracted from Initiative, in addition to carrying and silver penalties.';
 if(key==='peril_condition_track')return 'Peril track penalty is shown separately from the template skill total. Steam-powered gives +1/+2/+3 Initiative at −5/−10/−15.';
 if(key==='peril_stress')return 'Stressed / Frightened / Terrified: −2/−4/−6 inflicted damage and peril. Disables Servant of the Steward; enables Supernatural Paranoia.';
 if(key==='damage_condition_track')return 'Seriously / Grievously Wounded or Dying enables Warg-blooded’s +3 Damage Threshold.';
 if(key==='starving')return 'While starving, Broad-bellied’s +2 Peril Threshold is inactive.';
 if(key==='peril_situational')return 'Adds directly to final Peril Threshold.';
 if(key==='damage_situational')return 'Adds directly to final Damage Threshold.';
 if(key==='initiative_temporary')return 'Adds directly to final Initiative.';
 if(key==='reward_points')return 'Remaining RP = earned RP minus spent RP. The first 9 purchased Basic advances are free.';
 if(key==='reward_unique')return 'Each unique advance costs 10 RP.';
 if(key==='corruption'||key==='corruption_permanent')return 'Combined in the Overview corruption total; permanent corruption is also shown separately.';
 return '';
}
function field(f){if(f.key==='imageid')return '';const v=current.values[f.key]??'',id='field-'+f.key+'-'+Math.random().toString(36).slice(2);let control;const common=`id="${id}" data-key="${esc(f.key)}" ${current.locked?'disabled':''} ${fieldHint(f.key)?`aria-describedby="${id}-hint" title="${esc(fieldHint(f.key))}"`:''}`;
 if(f.type==='select')control=`<select ${common}>${f.options.map(o=>`<option value="${esc(o.value)}" ${v===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;
 else if(f.type==='textarea')control=`<textarea ${common}>${esc(v)}</textarea>`;
 else control=`<input ${common} type="${esc(f.type==='checkbox'?'checkbox':f.type==='number'?'number':'text')}" ${f.type==='checkbox'?(v===true||v===1||v==='1'?'checked':''):`value="${esc(v)}"`} ${['min','max','placeholder'].filter(k=>f[k]!=null).map(k=>`${k}="${esc(f[k])}"`).join(' ')}>`;
 const hint=fieldHint(f.key);return `<label for="${id}">${hint?`<span class="info-label field-hint" id="${id}-hint">${esc(hint)}</span>`:''}<span class="field-caption">${esc(f.label)}</span>${control}</label>`;}
function advancement(s){
 if(s.title==='Reward Points'){
  const c=calculate(current.values);
  return `<article class="card advancement-card"><h3>Reward Points</h3><div class="reward-grid">${s.fields.map(field).join('')}<label><span class="field-caption">Total RP spent (first 9 Basic advances free)</span><output id="adv-spent">${c.spent}</output></label><label><span class="field-caption">RP remaining for advancement</span><output id="adv-left">${c.left}</output></label></div><p class="adv-note">Basic: 10 RP · Intermediate: 20 RP · Advanced: 30 RP · Unique: 10 RP · First 9 purchased Basic advances are free. Totals update immediately.</p></article>`;
 }
 const tier=TIERS.find(t=>s.fields.some(f=>f.key===`profession_${t}_name`));
 if(!tier)return null;
 const p=`profession_${tier}_`,byKey=Object.fromEntries(s.fields.map(f=>[f.key,f]));
 const control=(key,label)=>field({...byKey[p+key],label});
 const row=(label,keys,toggle)=>`<div class="advance-row"><div class="advance-label">${label}</div><div class="advance-controls ${keys.length>1?'talent-controls':''}">${keys.map((k,i)=>control(k,`${tier} ${label}${i===1?' description':''}`)).join('')}</div><div class="advance-purchase">${control('toggle_'+toggle,`Purchased` )}</div></div>`;
 let rows='';for(let i=1;i<=6;i++)rows+=row('Skill Rank '+i,['skill_'+i],i);
 rows+=row('Attribute Adjustment',['attribute'],7);
 rows+=row('Professional Talent',['profession_talent','profession_talent_desc'],8);
 rows+=row('Ancestral Talent',['ancestral_talent','ancestral_talent_desc'],9);
 for(let i=1;i<=6;i++)rows+=row('Attribute Modifier '+i,['bonus_'+i],9+i);
 for(let i=1;i<=3;i++)rows+=row('General Talent '+i,['talent_'+i,'talent_'+i+'_desc'],15+i);
 return `<article class="card advancement-card profession-card"><h3>${tier[0].toUpperCase()+tier.slice(1)} Profession <small>${(TIERS.indexOf(tier)+1)*10} RP / advance</small></h3><div class="profession-name">${control('name','Profession Name')}</div><div class="advance-rows">${rows}</div><p class="adv-note">Automatic keyword effects require Purchased. Focus an input to see its calculation hint.</p></article>`;
}
function updateAdvancement(){const c=calculate(current.values);if($('adv-spent'))$('adv-spent').textContent=c.spent;if($('adv-left'))$('adv-left').textContent=c.left;}
function magicConfig(kind){return kind==='spell'?{title:'Spells',single:'Spell',prefix:'magic_',count:'spells_count',size:9,max:20}:{title:'Rituals',single:'Ritual',prefix:'ritual_',count:'rituals_count',size:7,max:10};}
function magicCount(values,kind){const config=magicConfig(kind);let populated=0;for(let i=1;i<=config.max;i++)if(SECTIONS.find(s=>s.title===config.title).fields.slice((i-1)*config.size,i*config.size).some(f=>values[f.key]!==undefined&&values[f.key]!==''&&values[f.key]!==null))populated=i;return Math.min(config.max,Math.max(populated,Math.floor(Number(values[config.count])||0)));}
function changeMagic(values,kind,action,index){const c=magicConfig(kind),count=magicCount(values,kind),fields=SECTIONS.find(s=>s.title===c.title).fields;
 if(action==='add'){if(count<c.max)values[c.count]=count+1;return;}
 if(action!=='remove'||!Number.isInteger(index)||index<1||index>count)return;
 for(let slot=index;slot<=count;slot++)for(const f of fields.slice((slot-1)*c.size,slot*c.size)){const next=f.key.replace(/_\d+$/,'_'+(slot+1));if(slot<count&&Object.hasOwn(values,next))values[f.key]=values[next];else delete values[f.key];}
 values[c.count]=count-1;
}
function magicSection(kind,printing=false){const c=magicConfig(kind),count=magicCount(current.values,kind),fields=SECTIONS.find(s=>s.title===c.title).fields;
 if(printing&&!count)return '';
 const records=Array.from({length:count},(_,i)=>`<article class="magic-record"><div class="magic-record-heading"><h4>${c.single} ${i+1}</h4><button type="button" class="no-print" data-magic-action="remove" data-magic-kind="${kind}" data-magic-index="${i+1}" aria-label="Remove ${c.single.toLowerCase()} ${i+1}" ${current.locked?'disabled':''}>Remove</button></div><div class="magic-fields">${fields.slice(i*c.size,(i+1)*c.size).map(f=>`<div class="${f.type==='textarea'?'magic-long-field':''}">${field({...f,placeholder:''})}</div>`).join('')}</div></article>`).join('');
 return `<section class="card magic-card"><div class="magic-section-heading"><h3>${c.title}</h3><span>${count} / ${c.max}</span><button type="button" class="no-print" data-magic-action="add" data-magic-kind="${kind}" ${count>=c.max||current.locked?'disabled':''}>Add ${c.single.toLowerCase()}</button></div>${records||`<p class="magic-empty">No ${c.title.toLowerCase()} added.</p>`}</section>`;
}
function section(s,printing=false){if(s.title==='Spells'||s.title==='Rituals')return magicSection(s.title==='Spells'?'spell':'ritual',printing);const layout=advancement(s);if(layout)return layout;return `<article class="card"><h3>${esc(s.title)}</h3><div class="fields">${s.fields.map(field).join('')}</div></article>`;}
function equipmentLayout(){
 const sections=SECTIONS.filter(s=>!s.tracking&&group(s)==='Equipment'),fields=Object.fromEntries(sections.flatMap(s=>s.fields).map(f=>[f.key,f]));
 const input=(key,label)=>field({...fields[key],placeholder:'',label:label||fields[key].label});
 const panel=(title,kind,body)=>`<article class="card equipment-card equipment-${kind}"><h3>${title}</h3>${body}</article>`;
 const table=(headers,rows)=>`<div class="equipment-table-scroll"><table class="equipment-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const armor=panel('Armor & Clothing','armor',`<div class="equipment-armor-fields">${['armor_name','armor_dth','armor_bb','armor_qualities','armor_clothes'].map(k=>input(k)).join('')}</div>`);
 const weapons=panel('Weapons','weapons',table(['','Weapon','Distance','Damage','Ammo (load)','Qualities'],Array.from({length:6},(_,i)=>['active','name','distance','damage','load','qualities'].map(k=>input(`weapon_${k}_${i+1}`)))));
 const tools=panel('Tools','tools',`<div class="equipment-lines">${Array.from({length:6},(_,i)=>input('tool_'+(i+1))).join('')}</div>`);
 const objects=panel('Small Objects','objects',`<div class="equipment-objects-list">${['memento',...Array.from({length:9},(_,i)=>'object_'+(i+2))].map((k,i)=>`<div class="equipment-object ${i===0?'memento-line':''}"><span>${i===0?'Memento':i+'.'}</span>${input(k,i===0?'Memento':'Small object '+i)}</div>`).join('')}</div>`);
 const supplies=panel('Supplies','supplies',table(['Supply','Rating'],Array.from({length:6},(_,i)=>[input('supply_name_'+(i+1)),input('supply_rating_'+(i+1))])));
 const titles=panel('Titles and Deeds','titles',`<div class="equipment-lines">${input('property')}</div>`);
 const burden=panel('Extra Burden I Carry','burden',`<div class="equipment-burden-fields">${input('burden')}${input('burden_penalty')}</div>`);
 const silver=panel('Silver Pieces','silver',`<div class="equipment-silver-field">${input('silver')}</div>`);
 return `<div class="equipment-layout">${armor}${weapons}${tools}${objects}${supplies}${titles}${burden}${silver}</div>`;
}
function personalLayout(){
 const get=title=>SECTIONS.find(s=>(!s.tracking||title==='Corruption')&&s.title===title);
 const card=(title,kind)=>{const s=get(title);const fields=s.fields.map(f=>field(title==='Attributes'?{...f,label:f.label.replace('Attribute ','')}:f)).join('');
 return `<article class="card personal-card personal-${kind}"><h3>${esc(title)}</h3><div class="personal-fields">${fields}</div>${title==='Attributes'?'<p class="personal-note">Enter base attribute values. Skill ranks and attribute advances are tracked in Advancement via profession toggles.</p>':''}</article>`;};
 return `<div class="personal-layout"><div class="personal-top-main">${card('Identity','identity')}<div id="portrait-controls" class="no-print">${portraitEditor()}</div>${card('Appearance','appearance')}</div><div class="personal-top-side">${card('Attributes','attributes')}</div><div class="personal-bottom-main">${card('Unique Bond','bond')}${card('Alignment & Corruption','alignment')}</div><div class="personal-bottom-side">${card('Goals','goals')}${card('Corruption','corruption')}${card('Reputation','reputation')}</div></div>`;
}
function overview(){
 const v=current.values,c=calculate(v),value=k=>esc(v[k]||'—'),txt=k=>`<div class="sheet-text">${value(k)}</div>`,info=t=>`<div class="info-label">${esc(t)}</div>`;
 const panel=(title,body,kind='')=>`<article class="sheet-panel ${kind}"><h3>${esc(title)}</h3>${body}</article>`;
 const rows=items=>`<table class="sheet-values"><tbody>${items.map(([label,val])=>`<tr><th scope="row">${esc(label)}</th><td>${esc(val)}</td></tr>`).join('')}</tbody></table>`;
 const parts=items=>`<details class="calculation-breakdown"><summary>Calculation breakdown</summary>${rows(items.map(p=>[p.label,p.value]))}</details>`;
 const squares=(count,max)=>`<span class="rank-marks" aria-label="${count} of ${max}">${Array.from({length:max},(_,i)=>`<span aria-hidden="true">${i<count?'■':'□'}</span>`).join('')}</span>`;
 const tracked=key=>{const f=SECTIONS.filter(s=>s.tracking).flatMap(s=>s.fields).find(f=>f.key===key);return f?field({...f,label:f.label.replace(/([a-z])([A-Z])/g,'$1 $2')}):'';};
 const identity=`<div class="sheet-story"><h2>My name is <strong>${value('name')}</strong> and I’m a <strong>${esc(highestProfession(v))}</strong></h2><p>I’m <strong>${[v.personal_age_group,v.personal_ancestry,v.personal_gender].filter(Boolean).map(esc).join(' ')||'—'}</strong>. I was born in <strong>${value('personal_season_of_birth')}</strong> in <strong>${value('personal_place_of_birth')}</strong>. I was raised in a/an <strong>${value('personal_upbringing')}</strong> home of the <strong>${value('personal_social_class')}</strong> class and became a follower of <strong>${value('personal_patron_deity')}</strong>.</p><p>I am of <strong>${value('personal_height')}</strong> stature and <strong>${value('personal_build')}</strong> build, with <strong>${value('personal_hair_color')}</strong> hair, <strong>${value('personal_eye_color')}</strong> eyes, <strong>${value('personal_complexion')}</strong> complexion and <strong>${value('personal_distinguishing_marks')}</strong>. My life changed the day that <strong>${esc(String(v.personal_death||'').trim()||'is shrouded in the fog of war')}</strong>. Yet I lived to tell the tale.</p><div class="story-line"><b>Inner Strength:</b> ${value('inner_strength')}</div><div class="story-line"><b>Tragic Flaw:</b> ${value('tragic_flaw')}</div></div>`;
 const history=panel(`Tainted by corruption: ${Number(v.corruption)||0} / 9 · Permanent corruption: ${Number(v.corruption_permanent)||0} · Total: ${c.corruption}`,`${txt('scars')}${info('Scars')}${txt('malignancies')}${info('Malignancies')}${txt('injuries')}${info('Injuries')}`);
 const goals=panel('My Goals & Ambitions',txt('personal_goals')),reputation=panel('I’m Known For',txt('reputation_text')+info('Current Reputation Points: '+(Number(v.reputation)||0)));
 const bio=`${identity}${history}${panel('Languages I Speak',txt('personal_language'))}`;
 const portrait=portraitSource(v.portrait);
 const attributes=`<table class="sheet-attributes"><thead><tr><th>Primary Attribute</th><th>Bonus Advances</th></tr></thead><tbody>${['Agility','Brawn','Combat','Perception','Intelligence','Willpower','Fellowship'].map(a=>`<tr><td><strong>${a}</strong><span class="attribute-score">${c.attributes[a].score}%</span></td><td>${squares(c.attributes[a].advances,6)}<div><b>${a} Bonus: ${c.attributes[a].bonus}</b></div><details class="attribute-breakdown"><summary>Details</summary>${rows([...c.attributes[a].scoreParts,...c.attributes[a].bonusParts].map(p=>[p.label,p.value]))}</details></td></tr>`).join('')}</tbody></table>`;
 const skills=`<table class="sheet-skills"><thead><tr><th>Skills</th><th>Ranks</th><th>Success</th></tr></thead><tbody>${Object.entries(c.skills).map(([skill,s])=>`<tr><th scope="row">${skill}</th><td>${squares(s.rank,3)}</td><td><span title="${esc(s.parts.map(p=>p.label+': '+p.value).join(' + '))}">${s.total}%</span>${c.perilPenalty?`<small class="current-skill">${s.current}% with Peril</small>`:''}</td></tr>`).join('')}</tbody></table>`;
 const skillPanel=panel('Attributes and Skills',`<div class="attributes-skills-layout">${attributes}${skills}</div>${info('Success includes purchased ranks, recognized ancestral talents and talismans. Hover a success total for its breakdown. Peril-adjusted totals are listed separately.')}`,'sheet-skills-panel');
 const threshold=(type,title)=>{const stat=c[type];return rows([['Base',stat.total],['Base +6',stat.total+6],['Base +12',stat.total+12],['Base +18',stat.total+18]])+parts(stat.parts);};
 const peril=panel('Peril Threshold',threshold('peril','Peril Threshold')+`<div class="overview-controls">${tracked('peril_condition_track')}${tracked('peril_stress')}${tracked('peril_situational')}${tracked('starving')}</div>`+info('Temporary condition penalty to damage and peril you inflict: '+c.stressPenalty),'sheet-peril');
 const armor=rows([['Worn Armor',v.armor_name||'—'],['DTh Modifier / adjusted',`${Number(v.armor_dth)||0} / ${c.armor}`],['BB Requirement',Number(v.armor_bb)||0],['Qualities',v.armor_qualities||'—'],['Worn Clothes',v.armor_clothes||'—']]);
 const damage=panel('Damage Threshold',threshold('damage','Damage Threshold')+`<div class="overview-controls">${tracked('damage_condition_track')}${tracked('damage_situational')}</div>`+(c.spiritualBlocked?info('Spiritual Defense is blocked by Heavy armor.'):'')+`<h4 class="sheet-subheading">Armor</h4>${armor}`,'sheet-damage');
 const weapons=panel('Weapons',`<div class="sheet-table-scroll"><table class="sheet-weapons"><thead><tr>${['','Weapon','Distance','Damage','Ammo (load)','Qualities'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${c.weapons.filter(w=>w.name).map(w=>`<tr><td>${w.active?'■':'□'}</td>${[w.name,w.distance,w.damage,w.load,w.qualities].map(x=>`<td>${esc(x||'—')}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="6">No weapons entered.</td></tr>'}</tbody></table></div>${info('Named weapons: '+c.totalWeapons+' / '+c.weaponsLimit+' before burden. Equip weapons on Equipment to apply Hardened and Defensive.')}`,'sheet-weapons-panel');
 const initiative=panel('Initiative Modifier',rows([['Base Initiative',c.initiative.base],['Burden',c.initiative.burden],['Final Initiative',c.initiative.total]])+parts(c.initiative.parts)+`<div class="overview-controls">${tracked('initiative_temporary')}${tracked('action_points')}</div>`,'sheet-initiative');
 const filled=key=>v[key]!==undefined&&v[key]!==null&&String(v[key]).trim()!=='';
 const toolKeys=Array.from({length:9},(_,i)=>'tool_'+(i+1)).filter(filled),tools=toolKeys.length?panel('Tools',toolKeys.map(txt).join(''),'sheet-tools'):'';
 const objectKeys=['memento',...Array.from({length:9},(_,i)=>'object_'+(i+2))].filter(filled),objects=objectKeys.length?panel('Small Objects',`<div class="sheet-objects-list">${objectKeys.map(k=>`<div class="${k==='memento'?'sheet-memento':''}">${k==='memento'?'<b>Memento:</b>':(Number(k.split('_')[1])-1)+'.'} ${value(k)}</div>`).join('')}</div>`+(filled('memento')?info('During a Brush With Death scene, holding your memento ignores Peril Track penalties.') : ''),'sheet-objects'):'';
 const supplySlots=Array.from({length:6},(_,i)=>i+1).filter(i=>filled('supply_name_'+i)||(filled('supply_rating_'+i)&&Number(v['supply_rating_'+i])!==0)),supplies=supplySlots.length?panel('Supplies',rows(supplySlots.map(i=>[v['supply_name_'+i]||'Supply',v['supply_rating_'+i]??'—']))+info('Maximum Supply Rating: '+c.supplyMax),'sheet-supplies'):'';
 const titles=filled('property')?panel('Titles and Deeds',txt('property'),'sheet-titles'):'',burden=filled('burden')||Number(v.burden_penalty)?panel('Extra Burden I Carry',(filled('burden')?txt('burden'):'')+info('Extra burden penalty: '+(Number(v.burden_penalty)||0)),'sheet-burden'):'',silver=panel('Silver Pieces',rows([['Silver',Number(v.silver)||0]])+info('Each full 1,000 SP adds 1 burden.'),'sheet-silver');
 const talents=panel('Talents',Object.entries(c.talentEntries).map(([type,entries])=>`<h4 class="talent-heading">${type} Talents</h4>${entries.map(e=>`<div class="sheet-text"><b>${esc(e.name||'Unnamed talent')}</b> ${esc(e.description)}</div>`).join('')||'<div class="sheet-text">—</div>'}`).join('')+`<h4 class="talent-heading">Unique Bond</h4>${txt('talent_unique_bond')}`,'sheet-talents');
 const magicContent=magicReadOnly(),magic=magicContent?`<div class="sheet-magic">${magicContent}</div>`:'';
 const ledger=panel('Reward Points',rows([['Total Reward Points',Number(v.reward_points)||0],['Lifepath credit used',c.free],['RP spent',c.spent],['RP remaining',c.left]]),'sheet-ledger');
 overviewParts={bio,goals,reputation,portrait:portrait?`<div class="sheet-portrait"><img src="${esc(portrait)}" width="256" height="256" alt="Character token"></div>`:'',skills:skillPanel,peril,damage,weapons,initiative,tools,objects,supplies,titles,burden,silver,talents,magic,ledger};
 $('overview').innerHTML=`<div class="sheet-overview"><div class="sheet-hero"><div class="sheet-bio">${bio}</div><div class="sheet-character-side">${portrait?`<div class="sheet-portrait"><img src="${esc(portrait)}" width="256" height="256" alt="Character token"></div>`:''}${goals}${reputation}</div></div><div class="sheet-combat">${skillPanel}${peril}${damage}${initiative}</div>${weapons}<div class="sheet-inventory">${tools}${objects}${supplies}${titles}${burden}${silver}</div>${talents}${magic}${ledger}</div>`;
}

function heading(){const portrait=$('character-portrait'),src=portraitSource(current.values.portrait);portrait.hidden=!src;if(src)portrait.src=src;else portrait.removeAttribute('src');$('character-name').textContent=current.values.name||'Unnamed survivor';$('subtitle').textContent=[current.values.personal_ancestry,...TIERS.slice().reverse().map(t=>current.values[`profession_${t}_name`]).filter(Boolean).slice(0,1)].filter(Boolean).join(' · ')||'Begin with a name. Build a life worth risking.';}
function characterCard(character){const v=character.values,portrait=portraitSource(v.portrait),selected=character.id===current.id,locked=character.locked===true,campaign=campaigns.find(c=>c.id===character.campaignId);
 return `<article class="gallery-card ${locked?'is-locked':''}" draggable="${!locked}" data-drag-character="${esc(character.id)}"><div class="gallery-portrait">${portrait?`<img src="${esc(portrait)}" width="256" height="256" alt="${esc(v.name||'Unnamed survivor')} portrait">`:'<span aria-hidden="true">⚔</span>'}</div><div class="gallery-card-body"><h4>${esc(v.name||'Unnamed survivor')}</h4><p class="gallery-profession">${esc(highestProfession(v))}</p><p class="muted">${esc([v.personal_ancestry,v.personal_gender].filter(Boolean).join(' ')||'Details not recorded')} <span class="gallery-inline-rp">${Number(v.reward_points)||0} RP</span></p>${selected?'<span class="gallery-current">Current character</span>':''}${locked?'<span class="gallery-lock-badge">Locked</span>':''}<label class="gallery-campaign-label">Campaign<select data-assign-character="${esc(character.id)}" ${locked?'disabled':''}><option value="">Unassigned</option>${campaigns.map(c=>`<option value="${esc(c.id)}" ${campaign?.id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="gallery-actions"><button type="button" data-gallery-action="open" data-character-id="${esc(character.id)}">Open character</button><button type="button" data-gallery-action="lock" data-character-id="${esc(character.id)}">${locked?'Unlock':'Lock'}</button><button type="button" class="gallery-remove" data-gallery-action="remove" data-character-id="${esc(character.id)}" ${locked?'disabled':''} aria-label="Remove ${esc(v.name||'Unnamed survivor')}">Remove</button></div></div></article>`;
}
function galleryLayout(){return `<section class="character-gallery"><div class="gallery-heading"><div><h3>Character Gallery</h3><p class="muted">${characters.length} saved character${characters.length===1?'':'s'}</p></div><button type="button" data-gallery-action="new">New character</button></div><div class="gallery-grid">${characters.map(characterCard).join('')}</div></section>`;}
function addCampaign(name){const clean=String(name||'').trim().slice(0,100);if(!clean){$('status').textContent='Enter a campaign name.';return null;}if(campaigns.some(c=>c.name.toLowerCase()===clean.toLowerCase())){$('status').textContent='A campaign with that name already exists.';return null;}const campaign={id:blank().id,name:clean};campaigns.push(campaign);persist();return campaign;}
function assignCampaign(characterId,campaignId){const character=characters.find(c=>c.id===characterId);if(!character||character.locked||campaignId&&!campaigns.some(c=>c.id===campaignId))return false;character.campaignId=campaignId||null;persist();render();return true;}
function toggleCharacterLock(id){const character=characters.find(c=>c.id===id);if(!character)return;character.locked=!character.locked;persist();render();if(storage)$('status').textContent=character.locked?'Character locked: editing and deletion disabled.':'Character unlocked.';}
function campaignLayout(id){const selected=campaigns.find(c=>c.id===id);
 if(selected){const assigned=characters.filter(c=>c.campaignId===id),unassigned=characters.filter(c=>!campaigns.some(p=>p.id===c.campaignId));return `<section class="character-gallery"><div class="gallery-heading"><div><h3>${esc(selected.name)}</h3><p class="muted">${assigned.length} assigned character${assigned.length===1?'':'s'}</p></div></div><div class="campaign-dropzone" data-drop-campaign="${esc(id)}"><h4>Campaign Characters</h4><div class="gallery-grid">${assigned.map(characterCard).join('')||'<p class="muted">Assign a character below, or drop one here.</p>'}</div></div><div class="campaign-dropzone" data-drop-campaign=""><h4>Unassigned Characters</h4><div class="gallery-grid">${unassigned.map(characterCard).join('')||'<p class="muted">No unassigned characters.</p>'}</div></div></section>`;}
 return `<section class="character-gallery"><div class="gallery-heading"><div><h3>Campaigns</h3><p class="muted">Create a campaign, then assign characters using their dropdown or drag a card onto a campaign.</p></div></div><form id="create-campaign-form" class="campaign-create"><label for="campaign-name">Campaign name<input id="campaign-name" maxlength="100" required placeholder="Enter a campaign name"></label><button type="submit">Create campaign tab</button></form><div class="campaign-zones">${campaigns.map(c=>`<div class="campaign-dropzone" data-drop-campaign="${esc(c.id)}"><h4>${esc(c.name)}</h4><p>${characters.filter(p=>p.campaignId===c.id).length} characters</p><button type="button" data-open-campaign="${esc(c.id)}">Open campaign</button></div>`).join('')}<div class="campaign-dropzone" data-drop-campaign=""><h4>Unassigned</h4><p>Drop a character here to remove its campaign assignment.</p></div></div><div class="gallery-grid">${characters.map(characterCard).join('')}</div></section>`;
}

function removeCharacter(id){const character=characters.find(c=>c.id===id);if(!character)return false;if(character.locked){$('status').textContent='Unlock this character before removing it.';return false;}const name=character.values.name||'Unnamed survivor';if(!window.confirm(`Remove “${name}” and its saved character sheet from this device? This cannot be undone.`))return false;
 characters=characters.filter(c=>c.id!==id);if(!characters.length)characters=[blank()];if(current.id===id)current=characters[0];persist();render();if(storage)$('status').textContent=`Removed ${name}`;return true;}
function aboutLayout(){return `<section class="about-page"><div class="about-intro"><p class="eyebrow">ZWEIHÄNDER REFORGED</p><h3>Character Forge</h3><p>An offline workshop for your survivors, campaigns and character sheets.</p></div><article class="card about-card"><h4>License</h4><p>This app is licensed under the <strong>GNU General Public License v3.0 (GPL-3.0)</strong>.</p><p>You may use, modify and redistribute the software under the terms of that license. The software is provided without warranty.</p><a href="https://github.com/Verencius/Zweihander-Reforged-Sheet-App/blob/main/LICENSE" target="_blank" rel="noopener noreferrer">Read the full license</a><p class="muted">This is an independent character-sheet tool. The software license does not grant rights to the Zweihänder name, game books, or other third-party material.</p></article><article class="card about-card"><h4>Source Code</h4><p>Explore the source, download the standalone app, or report an issue on GitHub.</p><a href="https://github.com/Verencius/Zweihander-Reforged-Sheet-App" target="_blank" rel="noopener noreferrer">Verencius / Zweihander-Reforged-Sheet-App</a></article><article class="card about-card about-support"><h4>Support the Project</h4><p>If Character Forge helps at your table, you can support Verencius on Buy Me a Coffee.</p><a class="coffee-link" href="https://buymeacoffee.com/Verencius" target="_blank" rel="noopener noreferrer">Buy Verencius a coffee</a><p class="muted">Support is optional. The app remains free to use.</p></article></section>`;}
function render(){document.body?.classList?.toggle('overview-mode',tab==='Overview');document.body?.classList?.toggle('gallery-mode',tab==='Gallery'||tab==='Campaigns'||tab==='About'||tab.startsWith('campaign:'));library();heading();$('nav').innerHTML=tabs.map(t=>`${t==='Gallery'?'<div class="nav-divider" role="separator"></div>':''}${t==='About'?'<div class="nav-divider" role="separator"></div>':''}<button data-tab="${esc(t)}" class="${tab===t?'active':''}" aria-current="${tab===t?'page':'false'}">${esc(t)}</button>${t==='Campaigns'&&campaigns.length?`<div class="campaign-nav-group">${campaigns.map(c=>`<button class="campaign-nav ${tab==='campaign:'+c.id?'active':''}" data-tab="campaign:${esc(c.id)}" aria-current="${tab==='campaign:'+c.id?'page':'false'}">${esc(c.name)}</button>`).join('')}</div>`:''}`).join('');$('lock-character').textContent=current.locked?'Unlock character':'Lock character';overview();$('overview').hidden=tab!=='Overview';$('editor').innerHTML=tab==='About'?aboutLayout():tab==='Gallery'?galleryLayout():tab==='Campaigns'?campaignLayout():tab.startsWith('campaign:')?campaignLayout(tab.slice(9)):tab==='Personal'?personalLayout():tab==='Equipment'?equipmentLayout():tab==='Advancement'?advancementLayout():SECTIONS.filter(s=>group(s)===tab).map(s=>section(s)).join('');}
$('nav').onclick=e=>{if(e.target.dataset.tab){tab=e.target.dataset.tab;render();}};
$('editor').addEventListener('click',e=>{const button=e.target.closest('[data-gallery-action]');if(!button)return;const action=button.dataset.galleryAction,id=button.dataset.characterId;if(action==='remove')removeCharacter(id);else if(action==='lock')toggleCharacterLock(id);else if(action==='open'){const character=characters.find(c=>c.id===id);if(character){current=character;tab='Overview';render();}}else if(action==='new')$('new').onclick();});
$('editor').addEventListener('input',e=>{const k=e.target.dataset.key;if(!k)return;if(current.locked)return;current.values[k]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value;persist();heading();library();overview();updateAdvancement();});
$('editor').addEventListener('click',e=>{const button=e.target.closest('[data-magic-action]');if(!button)return;const {magicAction:action,magicKind:kind,magicIndex:index}=button.dataset;if(!['spell','ritual'].includes(kind)||current.locked)return;changeMagic(current.values,kind,action,Number(index));persist();render();});
$('overview').addEventListener('change',e=>{const key=e.target.dataset.key;if(!key||current.locked)return;current.values[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value;persist();overview();});
$('editor').addEventListener('change',async e=>{if(e.target.id!=='portrait-upload'||current.locked)return;const file=e.target.files[0];if(!file)return;const character=current;e.target.disabled=true;$('status').textContent='Preparing 256 × 256 token…';
 try{const portrait=await tokenImage(file);if(character.locked||!characters.includes(character))return;character.values.portrait=portrait;character.values.portrait_filename=file.name;persist();if(current===character)render();}catch(error){$('status').textContent='Image upload failed: '+error.message;}finally{e.target.disabled=false;e.target.value='';}
});
$('editor').addEventListener('click',e=>{if(e.target.id==='remove-portrait'&&!current.locked){delete current.values.portrait;delete current.values.portrait_filename;persist();render();}});
$('lock-character').onclick=()=>toggleCharacterLock(current.id);
$('editor').addEventListener('submit',e=>{if(e.target.id!=='create-campaign-form')return;e.preventDefault();const campaign=addCampaign($('campaign-name').value);if(campaign){tab='campaign:'+campaign.id;render();}});
$('editor').addEventListener('change',e=>{const id=e.target.dataset.assignCharacter;if(id)assignCampaign(id,e.target.value);});
$('editor').addEventListener('click',e=>{const button=e.target.closest('[data-open-campaign]');if(button){tab='campaign:'+button.dataset.openCampaign;render();}});
$('editor').addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-character]');if(!card)return;const character=characters.find(c=>c.id===card.dataset.dragCharacter);if(!character||character.locked){e.preventDefault();return;}e.dataTransfer.setData('application/x-zweihander-character',character.id);e.dataTransfer.effectAllowed='move';});
$('editor').addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-campaign]');if(zone){e.preventDefault();e.dataTransfer.dropEffect='move';}});
$('editor').addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-campaign]');if(!zone)return;e.preventDefault();const id=e.dataTransfer.getData('application/x-zweihander-character');if(id)assignCampaign(id,zone.dataset.dropCampaign);});
$('library').onchange=()=>{current=characters.find(c=>c.id===$('library').value);render();};
$('new').onclick=()=>{current=blank();characters.push(current);tab='Personal';persist();render();};
$('export').onclick=()=>{const b=new Blob([JSON.stringify({format:'zweihander-forge',version:1,values:current.values,locked:!!current.locked,campaign:campaigns.find(c=>c.id===current.campaignId)?.name||null},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=(current.values.name||'character').replace(/[^\p{L}\p{N} _-]/gu,'')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('Choose a JSON file smaller than 2 MB.');const parsed=JSON.parse(await f.text()),v=parsed.values??parsed.variables??parsed;if(!v||typeof v!=='object'||Array.isArray(v)||!Object.keys(v).some(k=>k==='name'||k.startsWith('attribute_')))throw Error('This file does not contain character fields.');if(Object.values(v).some(x=>!['string','number','boolean'].includes(typeof x)&&x!==null))throw Error('Character fields must contain text, numbers, or checkboxes.');current=blank();current.values={...current.values,...v};current.locked=parsed.locked===true;if(typeof parsed.campaign==='string'&&parsed.campaign.trim()){const existing=campaigns.find(c=>c.name.toLowerCase()===parsed.campaign.trim().toLowerCase()),campaign=existing||addCampaign(parsed.campaign);if(campaign)current.campaignId=campaign.id;}characters.push(current);persist();render();$('status').textContent='Character imported';}catch(err){$('status').textContent='Import failed: '+err.message;}e.target.value='';};
let printing=false;function preparePrint(){if(printing){fitPrintPages();return;}overview();$('print-root').innerHTML=printMarkup();
 const root=$('print-root');root.querySelectorAll('.no-print,.field-hint,.calculation-breakdown,.attribute-breakdown').forEach(node=>node.remove());
 root.querySelectorAll('input,select,textarea').forEach(input=>{const output=document.createElement('span');output.className='print-field-value';output.textContent=input.tagName==='SELECT'?(input.options[input.selectedIndex]?.text||'—'):input.type==='checkbox'?(input.checked?'Yes':'No'):(input.value||'0');input.replaceWith(output);});
 // Duplicate editor IDs never enter the printed sheet.
 root.querySelectorAll('[id]').forEach(node=>{if(node.namespaceURI!=='http://www.w3.org/2000/svg')node.removeAttribute('id');});
 printing=true;document.body.classList.add('printing');fitPrintPages();}
window.addEventListener('beforeprint',preparePrint);window.addEventListener('afterprint',()=>{printing=false;document.body.classList.remove('printing');$('print-root').innerHTML='';});$('print').onclick=()=>{preparePrint();requestAnimationFrame(()=>{fitPrintPages();window.print();});};
render();if(!storage)$('status').textContent='Use Save JSON for a durable backup';else $('status').textContent='Autosave enabled · export JSON for a portable backup';
